CREATE TYPE "MessageRole" AS ENUM ('USER', 'ASSISTANT', 'SYSTEM');
CREATE TYPE "SearchStatus" AS ENUM ('PENDING', 'SUCCESS', 'EMPTY', 'FAILED');
CREATE TABLE "Session" ("id" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Session_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Conversation" ("id" TEXT NOT NULL, "sessionId" TEXT NOT NULL, "title" TEXT NOT NULL DEFAULT 'New conversation', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "lastMessageAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Conversation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Message" ("id" TEXT NOT NULL, "conversationId" TEXT NOT NULL, "role" "MessageRole" NOT NULL, "content" TEXT NOT NULL, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Message_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ConversationSummary" ("id" TEXT NOT NULL, "conversationId" TEXT NOT NULL, "content" TEXT NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ConversationSummary_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SearchExecution" ("id" TEXT NOT NULL, "conversationId" TEXT NOT NULL, "messageId" TEXT, "query" TEXT NOT NULL, "status" "SearchStatus" NOT NULL DEFAULT 'PENDING', "results" JSONB, "durationMs" INTEGER, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "SearchExecution_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ConversationSummary_conversationId_key" ON "ConversationSummary"("conversationId");
CREATE INDEX "Conversation_sessionId_lastMessageAt_idx" ON "Conversation"("sessionId", "lastMessageAt"); CREATE INDEX "Conversation_lastMessageAt_idx" ON "Conversation"("lastMessageAt"); CREATE INDEX "Message_conversationId_createdAt_idx" ON "Message"("conversationId", "createdAt"); CREATE INDEX "Message_createdAt_idx" ON "Message"("createdAt"); CREATE INDEX "SearchExecution_conversationId_createdAt_idx" ON "SearchExecution"("conversationId", "createdAt");
ALTER TABLE "Conversation" ADD CONSTRAINT "Conversation_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "Session"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Message" ADD CONSTRAINT "Message_conversationId_fkey" FOREIGN KEY ("conversationId") REFERENCES "Conversation"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ConversationSummary" ADD CONSTRAINT "ConversationSummary_conversationId_fkey" FOREIGN KEY ("conversationId") REFERENCES "Conversation"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "SearchExecution" ADD CONSTRAINT "SearchExecution_conversationId_fkey" FOREIGN KEY ("conversationId") REFERENCES "Conversation"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "SearchExecution" ADD CONSTRAINT "SearchExecution_messageId_fkey" FOREIGN KEY ("messageId") REFERENCES "Message"("id") ON DELETE SET NULL ON UPDATE CASCADE;
